#!/usr/bin/env python3
import csv,json,sys
from pathlib import Path
out=Path(sys.argv[1]);rows=list(csv.DictReader((out/'summary.csv').open()));audits=json.loads((out/'trace_audit.json').read_text())
primary=sorted([r for r in rows if r['mapping']=='stripe' and float(r['array_us'])==50 and r['mode']=='oracle'],key=lambda r:(int(r['L']),int(r['W'])))
base={(r['L'],r['W']):r for r in rows if r['mapping']=='stripe' and float(r['array_us'])==50 and r['mode']=='baseline'}
lines=['# SIFT100M：host 供給空窗與下一批 oracle 預讀','','## 範圍與結論','','實際跑了 36 組原生 MQSim TSU/PHY/NAND/event-engine 模擬；不是手算 latency。來源是 SIFT100M E_host（split BNF、page expansion、traverse_only）trace，不是 vanilla combined-layout DiskANN，也不是完整 CSD 搜尋。每組取原始前 1,000 個 query；只保留全部請求與所有批次能完整配對的 query，沒有補抽。','','在主模型（8 channels × 4 chips/channel × 2 dies/chip、50 μs array、4 KiB）下，預讀下一批可降低回放搜尋時間約 12–22%，但 NAND read 數、總 array 工作與實際 backend read latency 不變。平均 channel bus utilization 仍約 3–3.5%，不能宣稱已填滿。','','## 1. 空窗量測','','邊界：本批最後 block_rq_complete → 下一批第一筆 block_rq_issue。以應用程式的 query/beam/submit/completion timestamps 與 filefrag extents 對應後配對。block 事件只有 μs 精度；匹配允許邊界 ±1 μs。這不是 hardware doorbell/CQE 時刻，也不能拆成純 host stack；包含 host PQ、候選更新、其他 CPU 工作與量測成本。','','| L | W | 完整 query | 空窗 mean μs | p50 μs | p95 μs | 空窗 ≥ 62.578 μs |','|---:|---:|---:|---:|---:|---:|---:|']
for a in audits:
 name=Path(a['source']).name;L=name.split('_L')[1].split('_')[0];W=name.split('_W')[1];g=a['gap_us'];lines.append(f"| {L} | {W} | {a['accepted_queries']} | {g['mean']:.1f} | {g['p50']:.1f} | {g['p95']:.1f} | {a['single_read62578ns_gap_fraction']*100:.2f}% |")
lines+=['','62.578 μs = 0.290 μs command + 50 μs array + 12.288 μs data-out，是模型無競爭單筆 latency。不能只靠這個比較推論整批能完成，整批結果見下表。','','每個 baseline 模擬空窗內，這個 query 的 channel transfer 與 NAND array active 工作均為零（已驗證），所以孤立、單 query、無背景 I/O 的模型確實有資源可用。實體 trace 另有少量背景 I/O；gaps.csv 的 background_overlap 只標記已配對觀測到的背景請求，不能憑未標記就證明真機 NAND 閒置。','','## 2. Oracle 實驗','','同一組 query、batch、page 地址順序與批內 issue offsets。Baseline 在正式 demand 時讀；oracle 在上一批完成 + 1 ns 後開始提交下一批，保留相同批內 offsets。下一批正式到達時間 = 模擬上一批完成 + 原 trace gap，並非固定原始絕對時間。每次只預讀下一批，沒有跨越多輪。所有預讀都會被使用；首次 batch 無預讀。','','每筆正式 demand 與既有預讀合併，不重複讀。容量不限，但為隔離時序效果，兩邊都不做跨批持久 data-cache reuse；重複出現的 page 在兩邊都依 trace 再讀。因此這不是 infinite-cache upper bound。PQ／候選發現／VUC／額外 metadata I/O 成本設零；這是這個「下一批已知、批界開始預讀」政策的樂觀對照，不是所有 CSD 政策的數學全域最優。','','回放搜尋時間 = 模擬 first issue → last completion + 原 query total 減去實測 first issue → last completion 的固定起迄開銷；不含 full-vector exact rerank。Host gap 固定沿用 trace，並未重新執行 traversal。','','| L | W | Baseline ms | Oracle ms | 降幅 | 正式 demand 等待 μs：前→後 | 下一批整批提前就緒 |','|---:|---:|---:|---:|---:|---:|---:|']
for r in primary:
 b=base[r['L'],r['W']];lines.append(f"| {r['L']} | {r['W']} | {float(b['query_mean_us'])/1000:.3f} | {float(r['query_mean_us'])/1000:.3f} | {float(r['query_reduction_pct']):.1f}% | {float(b['request_demand_wait_us']):.2f} → {float(r['request_demand_wait_us']):.2f} | {float(r['next_batch_fully_ready_pct']):.1f}% |")
lines+=['','正式 demand 等待 = max(0, NAND transaction completion − 原本會需要此 request 的時間)，包含首批，不是 NAND intrinsic latency。整批提前就緒要求下一批所有 reads 在該批第一個 demand 到達前完成。','','### NAND 負擔與 latency 定義','','| 指標 | 結果 |','|---|---|','| NAND read 次數 | 完全相同，負擔下降 0% |','| 總 array sensing 工作 | 完全相同，下降 0% |','| 每次 array sensing | 50 μs → 50 μs |','| 實際 submit → complete（含 TSU queue） | 每組前後完全相同；約 72–104 μs |','| Command start → complete | 每組前後完全相同；約 65–69 μs |','| 正式 demand → 可用 | 明顯下降；大部分工作已提前完成 |','','本政策每次只提前一個 batch，批次內地址與提交節奏不變，沒有與其他批次的 NAND 工作競爭，因此同批的 backend latency 不變符合模型。真正改變的是 host 等待，不是 NAND 本身更快。','','### 資源利用率','','| L | W | 平均 channel bus busy：前→後 | Oracle 空窗內 channel busy |','|---:|---:|---:|---:|']
for r in primary:
 b=base[r['L'],r['W']];lines.append(f"| {r['L']} | {r['W']} | {float(b['channel_busy_pct']):.2f}% → {float(r['channel_busy_pct']):.2f}% | {float(r['gap_channel_busy_pct']):.2f}% |")
lines+=['','channel busy 只包含 command/address 和 data-out；分母為 8 channels × first-issue/last-completion window。Array sensing 不算 channel bus busy。預取把既有工作搬進空窗；同樣 bus 工作除以更短時間使平均比例增加，但一批做完仍需等 host。','','## 敏感度與限制','']
for m,ra in [('hash',50),('stripe',100)]:
 rr=[r for r in rows if r['mapping']==m and float(r['array_us'])==ra and r['mode']=='oracle'];v=[float(r['query_reduction_pct']) for r in rr];lines.append(f'- {m} mapping、array {ra} μs：平均回放時間降幅 {min(v):.1f}–{max(v):.1f}%。')
lines+=['','- LBA→channel/chip/die 是 stripe 或 splitmix64 模型，不是從真實 SSD 反推出的 FTL mapping。每個 die 內 unique pages 使用一對一緊湊地址，沒有 page alias。','- 使用原 TSU_OutOfOrder；read-only 路徑同 chip 串行，不會充分使用兩個 dies 的 interleaving。不能把該限制泛化成商用 controller。','- 無背景 query、GC、FTL mapping miss、PCIe、DRAM／ECC、VUC／候選評分成本。假設預測與覆蓋率皆 100%，仍不代表實際局部探索能做到。','- 本批 trace 的 host gap 包含大量 page-based PQ 與搜尋處理。不能據此宣稱 host I/O stack 本身有數百 μs，也不能直接套回先前 20% 的量測。','- 沒有改變搜尋路徑，未重新量測 recall；原 trace 是 traverse_only，不能報完整 ANN recall 或 exact-rerank 端到端延遲。','','## 驗證與產物','','36 組全部通過：完整 transaction 數量、phase 時序、固定 command/array/data 時長、channel bus 不重疊、die array 不重疊、原 scheduler chip 串行、配對政策完全相同地址與 gap、每 query oracle 不慢於 baseline。驗證記錄：validation.json。','','- `trace_audit.json`、各組 `audit.json`：來源、樣本排除與 gap 統計。','- 各組 `gaps.csv`：逐 beam 實測邊界及 host 階段分解。','- `summary.csv`：36 組彙整。','- 各組 `*_requests.csv`：逐 request 所有 NAND 階段與 demand 時間。','- 各組 `*_batches.csv`、`*_queries.csv`：逐批／逐 query 結果。','- `*_events.csv`：前 1,000 筆 requests 的 MQSim 事件。','- `results.png/svg`、`timeline.png/svg`：彙總及實際模擬時間軸。','','![Results](results.png)','','![Timeline](timeline.png)','']
(out/'REPORT.md').write_text('\n'.join(lines))
